/**
 * @name SSRF in aiohttp/httpx
 * @description Detects if a user-controlled URL is used in aiohttp or httpx requests.
 * @kind path-problem
 * @problem.severity error
 * @id py/aiobotocore/ssrf
 * @tags security
 *       external/cwe/cwe-918
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module SSRFConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // aiohttp request methods
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("aiohttp").getMember("ClientSession").getReturn().getMember(["get", "post", "put", "delete", "head", "options", "patch", "request"]).getACall() and
      sink = call.getArg(0)
    )
    or
    // httpx request methods
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("httpx").getMember("AsyncClient").getReturn().getMember(["get", "post", "put", "delete", "head", "options", "patch", "request"]).getACall() and
      sink = call.getArg(0)
    )
    or
    // httpx top-level methods
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("httpx").getMember(["get", "post", "put", "delete", "head", "options", "patch", "request"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module SSRFFlow = TaintTracking::Global<SSRFConfig>;
import SSRFFlow::PathGraph

from SSRFFlow::PathNode source, SSRFFlow::PathNode sink
where SSRFFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential SSRF from $@.", source.getNode(), "user input"
